import 'package:dm_tools_app_example/domain/auth_user.dart';
import 'package:dm_tools_app_example/services/auth_service.dart';
import 'package:dm_tools_app_example/services/default_auth_gateway.dart';
import 'package:dm_tools_app_example/services/default_auth_service.dart';
import 'package:dm_tools_app_example/services/session_store.dart';
import 'package:dm_tools_app_example/ui/home_page.dart';
import 'package:dm_tools_app_example/ui/login_page.dart';
import 'package:flutter/material.dart';
import 'package:sign_in_with_apple/sign_in_with_apple.dart';

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  final authService = DefaultAuthService(
    gateway: DefaultAuthGateway(),
    sessionStore: SessionStore(),
  );
  runApp(DmToolsApp(authService: authService));
}

/// Root widget: restores a persisted session ("remember me") on startup and
/// routes to [HomePage] or [LoginPage] accordingly.
class DmToolsApp extends StatefulWidget {
  const DmToolsApp({super.key, this.authService});

  /// Overridable for tests; defaults to the production wiring.
  final AuthService? authService;

  @override
  State<DmToolsApp> createState() => _DmToolsAppState();
}

class _DmToolsAppState extends State<DmToolsApp> {
  late AuthService _authService;
  late Future<AuthUser?> _session;
  bool? _appleAvailable;

  AuthService get _service => widget.authService ?? _authService;

  @override
  void initState() {
    super.initState();
    _authService = DefaultAuthService(
      gateway: DefaultAuthGateway(),
      sessionStore: SessionStore(),
    );
    _session = _service.restoreSession();
    _resolveAppleAvailability();
  }

  Future<void> _resolveAppleAvailability() async {
    try {
      final available = await SignInWithApple.isAvailable();
      if (mounted) setState(() => _appleAvailable = available);
    } on Exception {
      if (mounted) setState(() => _appleAvailable = false);
    }
  }

  void _onAuthenticated(AuthUser user) {
    setState(() {
      _session = Future.value(user);
    });
  }

  void _onSignedOut() {
    setState(() {
      _session = Future.value(null);
    });
  }

  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'DM Tools',
      theme: ThemeData(colorScheme: ColorScheme.fromSeed(seedColor: Colors.indigo)),
      home: FutureBuilder<AuthUser?>(
        future: _session,
        builder: (context, snapshot) {
          if (snapshot.connectionState != ConnectionState.done) {
            return const Scaffold(
              body: Center(child: CircularProgressIndicator()),
            );
          }
          final user = snapshot.data;
          if (user != null) {
            return HomePage(
              user: user,
              authService: _service,
              onSignedOut: _onSignedOut,
            );
          }
          return LoginPage(
            authService: _service,
            appleSignInAvailable: _appleAvailable ?? true,
            onAuthenticated: _onAuthenticated,
          );
        },
      ),
    );
  }
}

/// How the user authenticated.
enum AuthProvider {
  email,
  google,
  apple;

  String get label => switch (this) {
        AuthProvider.email => 'Email',
        AuthProvider.google => 'Google',
        AuthProvider.apple => 'Apple',
      };
}

/// A signed-in user, independent of the underlying identity provider.
class AuthUser {
  const AuthUser({
    required this.id,
    required this.email,
    required this.provider,
    this.displayName,
  });

  factory AuthUser.fromJson(Map<String, Object?> json) => AuthUser(
        id: json['id']! as String,
        email: json['email'] as String?,
        displayName: json['displayName'] as String?,
        provider: AuthProvider.values.byName(json['provider']! as String),
      );

  /// Provider-specific stable identifier.
  final String id;

  /// May be null for Apple sign-in re-authorizations, where Apple only
  /// shares the email on the first authorization.
  final String? email;

  final String? displayName;

  final AuthProvider provider;

  /// Best-effort display name for UI purposes.
  String get displayNameOrEmail => (displayName?.isNotEmpty ?? false)
      ? displayName!
      : (email?.isNotEmpty ?? false)
          ? email!
          : provider.label;

  Map<String, Object?> toJson() => <String, Object?>{
        'id': id,
        'email': email,
        'displayName': displayName,
        'provider': provider.name,
      };

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is AuthUser &&
          other.id == id &&
          other.email == email &&
          other.displayName == displayName &&
          other.provider == provider;

  @override
  int get hashCode => Object.hash(id, email, displayName, provider);

  @override
  String toString() =>
      'AuthUser(id: $id, email: $email, provider: ${provider.name})';
}

/// Generic authentication failure with a user-presentable message.
class AuthException implements Exception {
  const AuthException(this.message);

  final String message;

  @override
  String toString() => 'AuthException: $message';
}

/// The user aborted the flow (dismissed the account picker, cancelled the
/// platform dialog, ...). Not an error condition for the UI.
class AuthCancelledException extends AuthException {
  const AuthCancelledException([super.message = 'Sign-in was cancelled.']);
}

/// Shared client-side credential validation rules.
///
/// Used by both the login form (field-level errors) and the auth layer
/// (defensive re-check before calling a gateway).
abstract final class CredentialsValidator {
  static final RegExp _email = RegExp(r'^[\w.+-]+@[\w-]+(\.[\w-]+)+$');

  static bool isValidEmail(String value) => _email.hasMatch(value.trim());

  static bool isValidPassword(String value) => value.length >= 6;
}

