import 'dart:async';

import 'package:dm_tools_app_example/domain/auth_user.dart';
import 'package:dm_tools_app_example/services/auth_gateway.dart';
import 'package:dm_tools_app_example/services/auth_service.dart';

/// Deterministic users reused across tests.
const tEmailUser = AuthUser(
  id: 'local:user@example.com',
  email: 'user@example.com',
  displayName: 'user',
  provider: AuthProvider.email,
);

const tGoogleUser = AuthUser(
  id: 'google-42',
  email: 'google.user@gmail.com',
  displayName: 'Google User',
  provider: AuthProvider.google,
);

const tAppleUser = AuthUser(
  id: 'apple.001234.abcdef.1234',
  email: 'apple.user@icloud.com',
  displayName: 'Apple User',
  provider: AuthProvider.apple,
);

/// [AuthGateway] test double that records calls and returns canned users.
class FakeAuthGateway implements AuthGateway {
  FakeAuthGateway({
    this.emailUser = tEmailUser,
    this.googleUser = tGoogleUser,
    this.appleUser = tAppleUser,
    this.emailError,
    this.googleError,
    this.appleError,
  });

  final AuthUser emailUser;
  final AuthUser googleUser;
  final AuthUser appleUser;
  final Object? emailError;
  final Object? googleError;
  final Object? appleError;

  int emailCalls = 0;
  int googleCalls = 0;
  int appleCalls = 0;
  int signOutCalls = 0;
  String? lastEmail;
  String? lastPassword;

  @override
  Future<AuthUser> signInWithEmail(String email, String password) async {
    emailCalls++;
    lastEmail = email;
    lastPassword = password;
    final error = emailError;
    if (error != null) throw error;
    return emailUser;
  }

  @override
  Future<AuthUser> signInWithGoogle() async {
    googleCalls++;
    final error = googleError;
    if (error != null) throw error;
    return googleUser;
  }

  @override
  Future<AuthUser> signInWithApple() async {
    appleCalls++;
    final error = appleError;
    if (error != null) throw error;
    return appleUser;
  }

  @override
  Future<void> signOut() async {
    signOutCalls++;
  }
}

/// [AuthService] test double for widget tests.
class FakeAuthService implements AuthService {
  FakeAuthService({
    this.user = tEmailUser,
    this.restoredUser,
    this.error,
  });

  final AuthUser user;
  final AuthUser? restoredUser;
  final Object? error;

  int emailCalls = 0;
  int googleCalls = 0;
  int appleCalls = 0;
  int signOutCalls = 0;
  String? lastEmail;
  String? lastPassword;
  bool? lastRemember;

  @override
  Future<AuthUser> signInWithEmail(
    String email,
    String password, {
    required bool remember,
  }) async {
    emailCalls++;
    lastEmail = email;
    lastPassword = password;
    lastRemember = remember;
    final err = error;
    if (err != null) throw err;
    return user;
  }

  @override
  Future<AuthUser> signInWithGoogle({required bool remember}) async {
    googleCalls++;
    lastRemember = remember;
    final err = error;
    if (err != null) throw err;
    return user;
  }

  @override
  Future<AuthUser> signInWithApple({required bool remember}) async {
    appleCalls++;
    lastRemember = remember;
    final err = error;
    if (err != null) throw err;
    return user;
  }

  @override
  Future<AuthUser?> restoreSession() async => restoredUser;

  @override
  Future<void> signOut() async {
    signOutCalls++;
  }
}

/// [AuthService] whose email sign-in blocks until [complete] is called —
/// used to observe in-flight UI states.
class BlockingAuthService extends FakeAuthService {
  final Completer<AuthUser> _completer = Completer<AuthUser>();

  void complete() => _completer.complete(user);

  @override
  Future<AuthUser> signInWithEmail(
    String email,
    String password, {
    required bool remember,
  }) {
    emailCalls++;
    lastEmail = email;
    lastPassword = password;
    lastRemember = remember;
    return _completer.future;
  }
}

import 'package:dm_tools_app_example/domain/auth_exception.dart';
import 'package:dm_tools_app_example/services/default_auth_service.dart';
import 'package:dm_tools_app_example/services/session_store.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:shared_preferences/shared_preferences.dart';

import 'fakes.dart';

DefaultAuthService _service(FakeAuthGateway gateway) =>
    DefaultAuthService(gateway: gateway, sessionStore: SessionStore());

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  setUp(() {
    SharedPreferences.setMockInitialValues(<String, Object>{});
  });

  group('DefaultAuthService.signInWithEmail', () {
    test('persists the session when remember-me is on', () async {
      final gateway = FakeAuthGateway();
      final service = _service(gateway);

      final user = await service.signInWithEmail(
        'user@example.com',
        'secret123',
        remember: true,
      );

      expect(gateway.emailCalls, 1);
      expect(gateway.lastEmail, 'user@example.com');
      expect(gateway.lastPassword, 'secret123');
      expect(user, tEmailUser);

      final restored = await service.restoreSession();
      expect(restored, tEmailUser);
    });

    test('does not persist the session when remember-me is off', () async {
      final service = _service(FakeAuthGateway());

      final user = await service.signInWithEmail(
        'user@example.com',
        'secret123',
        remember: false,
      );

      expect(user, tEmailUser);
      expect(await service.restoreSession(), isNull);
    });

    test('propagates gateway failures without persisting', () async {
      final gateway = FakeAuthGateway(
        emailError: const AuthException('Invalid email or password.'),
      );
      final service = _service(gateway);

      await expectLater(
        service.signInWithEmail('user@example.com', 'secret123',
            remember: true),
        throwsA(isA<AuthException>()),
      );
      expect(await service.restoreSession(), isNull);
    });

    test('rejects malformed credentials before hitting the gateway', () async {
      final gateway = FakeAuthGateway();
      final service = _service(gateway);

      await expectLater(
        service.signInWithEmail('not-an-email', 'secret123', remember: true),
        throwsA(isA<AuthException>()),
      );
      expect(gateway.emailCalls, 0);
    });
  });

  group('DefaultAuthService federated sign-in', () {
    test('signInWithGoogle persists the Google user', () async {
      final gateway = FakeAuthGateway();
      final service = _service(gateway);

      final user = await service.signInWithGoogle(remember: true);

      expect(gateway.googleCalls, 1);
      expect(user, tGoogleUser);
      expect(await service.restoreSession(), tGoogleUser);
    });

    test('signInWithApple persists the Apple user', () async {
      final gateway = FakeAuthGateway();
      final service = _service(gateway);

      final user = await service.signInWithApple(remember: true);

      expect(gateway.appleCalls, 1);
      expect(user, tAppleUser);
      expect(await service.restoreSession(), tAppleUser);
    });

    test('federated failure with remember-me leaves no session', () async {
      final gateway = FakeAuthGateway(
        googleError: const AuthException('Google sign-in failed.'),
      );
      final service = _service(gateway);

      await expectLater(
        service.signInWithGoogle(remember: true),
        throwsA(isA<AuthException>()),
      );
      expect(await service.restoreSession(), isNull);
    });
  });

  group('DefaultAuthService.signOut', () {
    test('clears the session and signs out of the gateway', () async {
      final gateway = FakeAuthGateway();
      final service = _service(gateway);
      await service.signInWithEmail('user@example.com', 'secret123',
          remember: true);

      await service.signOut();

      expect(gateway.signOutCalls, 1);
      expect(await service.restoreSession(), isNull);
    });
  });
}

